"""Embedded, non-tracking brand art and a related HTML MIME part for email clients."""
import base64
from email.mime.image import MIMEImage
from django.conf import settings
from django.core.mail import EmailMultiAlternatives
from django.core.mail.message import SafeMIMEMultipart

# Auth-page hexagonal A and decorative brown arcs, embedded to avoid remote image URLs.
BRAND_IMAGES = {'mark': '', 'mark-light': '', 'hero': ''}


class BrandedEmailMultiAlternatives(EmailMultiAlternatives):
    """Preserve plain text and file attachments; group HTML with its CID images."""
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.extra_headers['X-Artisan-Email-Design'] = 'signin-v32'

    def _create_alternatives(self, msg):
        alternative = super()._create_alternatives(msg)
        if not alternative.is_multipart():
            return alternative
        parts = alternative.get_payload()
        for index, part in enumerate(parts):
            if part.get_content_type() != 'text/html':
                continue
            related = SafeMIMEMultipart(_subtype='related', encoding=self.encoding or settings.DEFAULT_CHARSET)
            related.attach(part)
            for name, encoded in BRAND_IMAGES.items():
                image = MIMEImage(base64.b64decode(encoded), _subtype='png')
                image.add_header('Content-ID', f'<artisan-{name}-v32>')
                image.add_header('Content-Disposition', 'inline', filename=f'artisan-{name}.png')
                related.attach(image)
            parts[index] = related
        alternative.set_payload(parts)
        return alternative
